export function Parallax({
  enabled = {{enabled}},
  duration = {{duration}},
  direction = "{{direction}}",
  accent = "{{accent}}",
}) {
  const suffix = direction === "horizontal" ? "h" : "v";
  const on = enabled ? "on" : "";
  return (
    <div data-direction={direction} style={{ position: "relative", width: "100%", maxWidth: 320, height: 120, background: "linear-gradient(#D9C8F0, #FAF7F2)", borderRadius: 12, overflow: "hidden", border: "1px solid #24143022", fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div className={`back ${on}`} style={{ position: "absolute", borderRadius: 999, width: 40, height: 40, top: 12, left: 20, background: "#BFD9F244" }} />
      <div className={`mid ${on}`} style={{ position: "absolute", borderRadius: 999, width: 26, height: 26, top: 46, left: 90, background: "#A8E6C199" }} />
      <div className={`front ${on}`} style={{ position: "absolute", borderRadius: 999, width: 16, height: 16, top: 78, left: 160, background: accent }} />
      <p style={{ position: "absolute", bottom: 4, left: 8, right: 8 }}>Parallax {enabled ? "on" : "off"} &middot; layers move at different speeds for depth</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .back.on { animation: mot-plx-${suffix}-slow ${duration}s linear infinite; }
          .mid.on { animation: mot-plx-${suffix}-mid ${duration}s linear infinite; }
          .front.on { animation: mot-plx-${suffix}-fast ${duration}s linear infinite; }
          @keyframes mot-plx-h-slow { 0%,100% { transform: translateX(0); } 50% { transform: translateX(20px); } }
          @keyframes mot-plx-h-mid { 0%,100% { transform: translateX(0); } 50% { transform: translateX(-40px); } }
          @keyframes mot-plx-h-fast { 0%,100% { transform: translateX(0); } 50% { transform: translateX(-80px); } }
          @keyframes mot-plx-v-slow { 0%,100% { transform: translateY(0); } 50% { transform: translateY(10px); } }
          @keyframes mot-plx-v-mid { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-16px); } }
          @keyframes mot-plx-v-fast { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-28px); } }
        }
      `}</style>
    </div>
  );
}
